const items = $input.all();
const item = items[0] && items[0].json ? items[0].json : {};
const found = item.found || 0;
const results = Array.isArray(item.results) ? item.results : [];
const zones = Array.isArray(item.zones) ? item.zones : [];
const catalogo = Array.isArray(item.catalogo_compacto) ? item.catalogo_compacto : [];

// Fix 7-sep-2026: el subworkflow dice ahora si el resultado coincide DE VERDAD con la calle o
// urbanizacion que pidio el cliente. Defensivo: si no viene (subworkflow viejo), 'exact'.
const matchQuality = item.match_quality || 'exact';
const requestedTerms = Array.isArray(item.requested_terms) ? item.requested_terms : [];
const requestedLocationText = (item.requested_location_text || '').toString().trim();
const unmatchedTerms = Array.isArray(item.unmatched_terms) ? item.unmatched_terms : [];

if (!found || results.length === 0) {
  // Build Zones YA calcula el mensaje correcto en todos los casos (enriquecido con
  // poblaciones cercanas, fuera de zona de operacion, o el generico de siempre) --
  // confiar siempre en item.message cuando esta presente, sin condicionarlo a zones
  // (el caso 'fuera de zona' no tiene vecinos que listar y aun asi es un mensaje valido).
  const message = item.message
    || 'No tengo viviendas con esos criterios ahora mismo. ¿Ampliamos la zona o subimos un poco el presupuesto?';
  return [{ json: {
    message,
    count: 0,
    total_in_catalog: 0,
    results: [],
    zones,
    catalogo_compacto: [],
    match_quality: 'none',
    requested_terms: requestedTerms,
    requested_location_text: requestedLocationText,
    unmatched_terms: unmatchedTerms
  }}];
}

const top = results.slice(0, 2);
// Fix 9-sep-2026: se locutaban dos viviendas y ademas se DECIA "Tengo dos" con independencia
// de cuantas hubiera: "que casas teneis" -> "Tengo dos" con 12 en cartera, y Villaviciosa de
// Odon (3: el piso de Centro y los dos chalets de El Bosque) se quedaba en dos, sin nombrar
// nunca el mas caro. Ahora se dice el numero REAL y se avisa de que se nombran dos; el resto
// sigue viajando al agente en catalogo_compacto, asi que puede contarlas si el cliente pregunta.
const CARDINAL = ['cero','una','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez',
                  'once','doce','trece','catorce','quince','dieciseis','diecisiete','dieciocho',
                  'diecinueve','veinte'];
const num = n => CARDINAL[n] || String(n);

// Con 3 o mas no se recitan dos viviendas: se PREGUNTA por el eje que de verdad separa lo que
// hay, y solo por el que el cliente no ha fijado ya (si pidio municipio, todas comparten
// municipio y ese eje se salta solo). Orden: zona -> tipo -> presupuesto. 'catalogo_compacto'
// trae TODAS las encontradas, no solo las dos que se locutan, asi que el recuento es real.
const TIPO_PALABRA = { piso: ['piso', 'pisos'], chalet: ['chalet', 'chalets'],
  duplex: ['dúplex', 'dúplex'], 'local-oficina': ['local', 'locales'], otro: ['inmueble', 'inmuebles'] };
const listar = xs => (xs.length <= 1 ? (xs[0] || '') : xs.slice(0, -1).join(', ') + ' y ' + xs[xs.length - 1]);
const porFrecuencia = (arr) => {
  const c = new Map();
  arr.filter(Boolean).forEach(v => c.set(v, (c.get(v) || 0) + 1));
  return [...c.entries()].sort((a, b) => b[1] - a[1]);
};
function preguntaFiltro(prefijo) {
  const cat = catalogo.length ? catalogo : top;
  if (cat.length < 3) return null;
  const munis = porFrecuencia(cat.map(r => r.zona));
  if (munis.length > 1) {
    const nombres = munis.slice(0, 3).map(([m]) => municipioLimpio(m));
    const cola = munis.length > 3 ? ', entre otras zonas' : '';
    return prefijo + num(found) + ', repartidas por ' + listar(nombres) + cola + '. ¿Por qué zona te interesa?';
  }
  const donde = municipioLimpio(munis[0] ? munis[0][0] : '');
  const tipos = porFrecuencia(cat.map(r => r.tipo));
  if (tipos.length > 1) {
    const trozos = tipos.map(([t, n]) => {
      const par = TIPO_PALABRA[t] || ['inmueble', 'inmuebles'];
      return (n === 1 ? 'un ' + par[0] : num(n) + ' ' + par[1]);
    });
    return prefijo + num(found) + (donde ? ' en ' + donde : '') + ': ' + listar(trozos) + '. ¿Qué prefieres?';
  }
  const precios = cat.map(r => r.precio).filter(p => typeof p === 'number' && p > 0);
  const min = Math.min.apply(null, precios), max = Math.max.apply(null, precios);
  if (precios.length && min !== max) {
    const par = TIPO_PALABRA[tipos[0] ? tipos[0][0] : ''] || ['inmueble', 'inmuebles'];
    return prefijo + num(found) + ' ' + par[1] + (donde ? ' en ' + donde : '') +
           ', entre ' + leerPrecio(min) + ' y ' + leerPrecio(max) + '. ¿En qué presupuesto te mueves?';
  }
  return null;
}

function leerPrecio(p) {
  if (!p) return 'precio sin confirmar';
  if (p >= 1000000) { const m = (p / 1000000).toFixed(1).replace('.', ' coma '); return m + ' millones'; }
  if (p >= 1000) return Math.round(p / 1000) + ' mil euros';
  return p + ' euros';
}
function calleLimpia(s){
  if(!s||typeof s!=='string') return '';
  let out=s.trim();
  out = out.replace(/^(?:casa\s+o\s+)?(?:chalet|piso|ático|atico|casa|apartamento|estudio|dúplex|duplex|loft|adosado|pareado|finca|villa)(?:\s+(?:adosado|adosada|pareado|pareada|independiente|unifamiliar|individual))?\s+en\s+/i,'');
  const cp = out.match(/\b(\d{5})\b/);
  if(cp) out = out.slice(0, cp.index);
  out = out.split(',')[0].trim().replace(/[,\s]+$/,'').trim();
  return out;
}
function municipioLimpio(s){
  if(!s||typeof s!=='string') return '';
  return s.trim().replace(/\s+de\s+(Madrid|Barcelona|Valencia|Sevilla|Zaragoza|Málaga|Bilbao)$/i,'').trim();
}
function ubicBreve(v) {
  const calle = calleLimpia(v.direccion || '');
  const muni = municipioLimpio(v.municipio || '');
  if (calle && muni) return calle + ', ' + muni;
  if (calle) return calle;
  if (muni) return muni;
  return 'ubicación sin detallar';
}
// Lo que pidio el cliente, en algo hablable. Sin comillas ni markdown: va a un TTS.
function pedidoHablable() {
  const libre = requestedLocationText.replace(/["'`*_]/g, '').trim();
  if (libre && libre.split(/\s+/).length <= 6) return libre;
  if (unmatchedTerms.length) return unmatchedTerms.join(' ');
  return libre;
}

let message;
// 'partial' = hay viviendas que cumplen precio/metros pero NINGUNA esta en la calle o zona que
// pidio. Antes se locutaba 'Tengo una en X' y el agente la presentaba como si fuera la suya
// (bug del 5-sep, repetido tres veces en la misma llamada). Ahora se admite primero.
if (matchQuality === 'partial') {
  const pedido = pedidoHablable();
  const apertura = pedido
    ? 'En ' + pedido + ' no me sale nada ahora mismo.'
    : 'Con esos criterios exactos no me sale nada ahora mismo.';
  if (top.length === 1) {
    const v = top[0];
    message = apertura + ' Lo que sí tengo, por ' + leerPrecio(v.precio) + ', es en ' + ubicBreve(v) + '. ¿Te encaja o miramos otra zona?';
  } else {
    const a = top[0]; const b = top[1];
    const pregunta = found > 2 ? preguntaFiltro('Lo que sí tengo son ') : null;
    if (pregunta) {
      message = apertura + ' ' + pregunta;
    } else {
      const cabecera = found === 2
        ? ' Lo que sí tengo es una en '
        : ' Lo que sí tengo son ' + num(found) + '. Te digo dos: una en ';
      message = apertura + cabecera + ubicBreve(a) + ' por ' + leerPrecio(a.precio) + ', y otra en ' + ubicBreve(b) + ' por ' + leerPrecio(b.precio) + '. ¿Alguna te encaja?';
    }
  }
} else if (top.length === 1) {
  const v = top[0];
  message = 'Tengo una en ' + ubicBreve(v) + ' por ' + leerPrecio(v.precio) + '. ¿Te la describo o vamos a verla?';
} else {
  const a = top[0]; const b = top[1];
  const pregunta = found > 2 ? preguntaFiltro('Tengo ') : null;
  if (pregunta) {
    message = pregunta;
  } else {
    const cabecera = found === 2
      ? 'Tengo dos. Una en '
      : 'Tengo ' + num(found) + '. Te digo dos: una en ';
    const cierre = found === 2 ? '. ¿Cuál?' : '. ¿Alguna te encaja o te cuento las demás?';
    message = cabecera + ubicBreve(a) + ' por ' + leerPrecio(a.precio) + ', y otra en ' + ubicBreve(b) + ' por ' + leerPrecio(b.precio) + cierre;
  }
}

return [{ json: {
  message,
  count: top.length,
  total_in_catalog: found,
  results: top,
  zones,
  catalogo_compacto: catalogo,
  match_quality: matchQuality,
  requested_terms: requestedTerms,
  requested_location_text: requestedLocationText,
  unmatched_terms: unmatchedTerms
}}];

